+            let step = match b[i] {
+                0x00..=0x7F => 1,
+                0xC0..=0xDF => 2,
+                0xE0..=0xEF => 3,
+                _ => 4,
+            };
+            i += step.min(b.len() - i);
+        }
+    }
+    cuts.dedup();
+    let mut out = Vec::with_capacity(cuts.len());
+    for w in cuts.windows(2) {
+        out.push(&text[w[0]..w[1]]);
+    }
+    let last = *cuts.last().unwrap();
+    if last < text.len() {
+        out.push(&text[last..]);
+    }
+    out
